// valeurs du jeu par défaut pour tous les essais de conduite
function circuit({ R = 0, arc = Infinity, pente = 0, largeur = 12, limite = 20 } = {}) { ... }
// essai clavier : réglages réels et ligne tenue au clavier
const cmd = commande({ guidage: .15, aide: .35 });
// toutes les `on` s, lu à 30/60/120 Hz : touche de contre-braquage, touche vers l'intérieur ou rien
const u = -.5 - kd * dn - kp * psin - kb * (bn - .35);
cible = u < seuil ? -s : (u > 0 ? s : 0);
const ok = n3 && !evs.some(e => e.type === 'deriveAnnulee') && dMaxJusquAuPalier3 < 5.5;

const essai = aide => { /* même départ */ return { tq, bMax, bFin, dMin }; };
const sans = essai(0);
noter('forte glisse sans correction : tête-à-queue', +sans.tq, 'oui', sans.tq);
for (const aide of [.35, .7]) {
  const a = essai(aide);
  noter(`forte glisse, aide ${aide} : rattrapée`, a.bMax * deg, 'tête-à-queue sans aide, rattrapée avec',
        sans.tq && !a.tq && a.bFin * deg < 5 && a.dMin > -6);
}
// régler le choc de départ (β, ω) pour que l'aide 0 parte vraiment en tête-à-queue : sinon le critère n'est pas mesurable

// approche stabilisée ; « idéal » = meilleur d'une famille, cherché pour chaque rayon ; verdict sur [t0, t0 + 3 s]
const famille = p => (et, cmd) => {
  const s = et.derive.sens || 1, dn = s * et.d, ps = s * et.psi, bn = s * et.beta;
  cmd.volant = s * clamp(p.b - p.kd * dn - p.kp * ps - p.kb * (bn - p.bc), -1, .3);
  cmd.gaz = PLEIN_GAZ ? 1 : clamp(p.g0 + p.gp * ps, 0, 1); // hypothèse à faire trancher par David
};
let mieux = Infinity; // b {-.3,-.5,-.7} kd {0,.03,.1} kp {0,1,3,8} kb {0,1,3} bc {.2,.35} g0 {.2,.5,1} gp {0,5}
for (const p of grille) {
  const r = deriver(Rv, vRef(Rv), 3.2, famille(p), { approche: 6, largeur: 12, limite: 20 });
  const tr = r.trace.filter(x => x.t >= r.t0 && x.t <= r.t0 + 3);
  if (tr.every(x => x.actif)) mieux = Math.min(mieux, Math.max(...tr.map(x => Math.abs(x.d))));
}
noter(`dérive tenue en R ${Rv}`, mieux, '< 5,5', mieux < 5.5);

let mieux = null;
for (const tau of [0, .05, .1, .15, .2]) for (const q of [.25, .4, .5, .6, .75]) for (const ti of [.45, .7, 1]) {
  const r = deriver(120, vRef(120), 4, (et, cmd, t) => { cmd.volant = (t < tau ? ti : -q) * et.derive.sens; cmd.gaz = 1; },
                    { largeur: SUR_PISTE ? 12 : 400, limite: SUR_PISTE ? 20 : 500 });
  const p = paliers(r); if (!mieux || p[2] < mieux[2]) mieux = p;
}
noter('paliers de dérive au mieux (s)', mieux.map(x => x.toFixed(2)).join(' / '), '0,7 / 1,3 / 2,1',
      [.7, 1.3, 2.1].every((c, i) => Math.abs(mieux[i] - c) <= .05));

// glisse provoquée indépendamment du critère des 6° ; témoin sans contre-braquage ; gaz inchangé ; trajectoire surveillée
const rattrapage = contre => {
  const { et, c, cmd } = tenir(120, vl120 * .98, 8), b0 = et.beta;
  et.beta += KICK_B; et.omega += KICK_W; // réglés pour que le témoin parte en tête-à-queue
  const k = commande({ volant: cmd.volant, gaz: cmd.gaz });
  let t0 = -1, tq = false, bFin = 0, dMin = 0;
  rouler(et, c, k, 4, (et, k, t) => {
    if (t0 < 0 && et.beta - b0 > 4 / deg) t0 = t;            // virage à droite : glisse = β qui monte
    if (contre && t0 >= 0 && t >= t0 + .3) k.volant = contre(et);
    tq ||= Math.abs(et.beta) > Math.PI / 2; bFin = Math.abs(et.beta); dMin = Math.min(dMin, et.d);
  });
  return { t0, tq, bFin, dMin };
};
const sans = rattrapage(null), avec = rattrapage(et => clamp(-et.beta / .25, -.8, .8));
const ok = sans.tq && avec.t0 >= 0 && !avec.tq && avec.bFin * deg < 3 && avec.dMin > -6;

// circuit : droite d'approche de 150 m, arc de 180° en R 80, puis 200 m de droite (circuit() à étendre)
// dérive tenue jusqu'à la sortie, lâcher en sortie au palier 3 ; pas de frein tant que le turbo pousse
if (avecDerive && enVirage) { cmd.derive = true; contre(et, cmd); } else cmd.derive = false;
if (et.turbo.reste > 0) cmd.frein = 0;
const tu = evs.find(e => e.type === 'turbo');
noter('R 80 : dérive puis turbo III, gain (s)', g, '0,1 à 0,3', !!tu && tu.niveau === 3 && g >= .1 && g <= .3);

// 3e à la limite du R 120 ; 2e à la limite d'un rayon où elle est possible (vLimite(R) ≈ 0,9 × 40 m/s, R ≈ 60 à 70 m : à faire valider par David)
for (const [rap, Rr] of [[2, R2E], [3, 120]]) {
  const vg = vLimite(Rr) * .98; /* tenir(Rr, vg, 8, { rapport: rap }) puis plein gaz */
  bMax[rap] = Math.max(bMax[rap], P.sens * et.beta); // nez vers l'intérieur ; ou et.deriveAr selon la lecture retenue
}
noter('plein gaz en 2e ou 3e : glisse de l\'arrière (°)', Math.max(bMax[2], bMax[3]) * deg, '≥ 6', Math.max(bMax[2], bMax[3]) * deg >= 6);

const scenarios = [rPaliers, ...rTenues, ...rClaviers, rLacher];
for (const hz of [120, 60]) {
  const m = Math.max(...scenarios.map(r => d2betaMax(r.betas, hz)));
  noter(`lissage de la glisse à ${hz} Hz (pire scénario)`, m * deg, '≤ 300', m * deg <= 300);
}

for (const [R, guidage] of [[0, 0], [150, .15], [300, .15]]) for (const kmh of [120, 200, 300]) {
  const c = circuit({ R }), et = CD.creer(0, 0); et.v = kmh / 3.6;
  rouler(et, c, commande({ volant: 1, guidage }), 2, ...);
  // rapport mesuré à la vitesse courante : |omega| / (capaciteLaterale(v) / v)
}

// vrai choc : la glissière avant l'herbe (largeur 44, limite 20), voiture lancée vers le mur
const c2 = circuit({ largeur: 44, limite: 20 }), e3 = base(); e3.d = -19.9; e3.psi = -.3;
let choc = false;
for (let i = 0; i < 3; i++) for (const e of CD.pas(e3, commande({ gaz: 1 }), c2, DT)) choc ||= e.type === 'choc';
const k = choc && e3.turbo.reste === 0;
// et un contact voiture contre voiture : deux voitures côte à côte dans B.course, un pas de B.course.pas

for (const v0 of [86, 92]) { // 92 m/s : pointe sous turbo
  const et = CD.creer(0, 0); et.v = v0; let av = null, arme = false;
  for (let i = 0; i < 300 && av === null; i++) {
    CD.pas(et, commande({ frein: 1 }), c, DT);
    if (arme) av = et.chargeAv; // chargeAv est calculé avec le chargeX du pas précédent
    arme = et.chargeX <= -3 * G;
  }
  if (av !== null) noter(`charge avant à −3 g, freinage depuis ${v0} m/s`, av, '≥ 0,60', av >= .6);
}
// accélération : chargeAv < P.repartition en 2e plein gaz

const tr = r.trace.filter(x => x.t >= r.t0 && x.t <= r.t0 + 3);
const ok = tr.every(x => x.actif) && Math.max(...tr.map(x => Math.abs(x.d))) < 5.5;
// indiquer la vitesse au départ de la dérive dans l'info

for (let i = 0; i < 1200; i++) {
  CD.pas(et, cmd, c, DT); const t = (i + 1) * DT;
  if (t <= .5 + 1e-9) rMin = Math.min(rMin, et.regime);
  if (t100 < 0 && et.v * 3.6 >= 100) t100 = t;
}

